#!/bin/sh
# Stamps VERSION (and the commit, when the builder knows it) into the API and web sources.
# Called by `./task build`; `./task check` fails when the generated files drift from VERSION.
set -eu

root=$(cd "$(dirname "$0")/.." && pwd)
version=$(tr -d ' \n\r' < "$root/VERSION")

case "$version" in
  '' | *[!0-9.]*)
    echo "error: VERSION is not plain semver: '$version'" >&2
    exit 1
    ;;
esac
case "$version" in
  *.*.*) ;;
  *)
    echo "error: VERSION must be X.Y.Z (got '$version')" >&2
    exit 1
    ;;
esac

commit=${KRAN_COMMIT:-}
case "$commit" in
  *[!0-9a-f]*)
    echo "error: KRAN_COMMIT must be lowercase hex (got '$commit')" >&2
    exit 1
    ;;
esac

cat >"$root/apps/api/src/version_gen.nim" <<NIM
## JANGAN EDIT — dihasilkan tools/gen-version.sh dari VERSION saat build.

const AppVersion* = "$version"
const AppCommit* = "$commit"
NIM

cat >"$root/apps/web/src/lib/version.ts" <<TS
// Generated by tools/gen-version.sh from VERSION. Do not edit by hand.
export const APP_VERSION = "$version";
export const APP_COMMIT = "${commit:-none}";
TS

printf 'version: %s (commit %s)\n' "$version" "${commit:-none}"
